import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createHalEngine} from '../config.js';
import {createServer} from './createServer.js';
import type {HalServerOptions} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator, deferred} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {SessionStore} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

interface WireSummary {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

interface Frame {
  type: string;
  code?: string;
  message?: string;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  conversations?: WireSummary[];
}

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

beforeAll(() => {
  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
});

afterAll(() => {
  setLogger();
});

afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
});

const startServer = async (
  store: SessionStore,
  options: {history?: {enabled: boolean}; resume?: {enabled: boolean}; orchestrator?: ChatOrchestrator} = {}
) => {
  const auth = {userId: 'u1'};
  const serverOptions = {
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: auth.userId}),
    sessionStore: store,
    orchestrator: options.orchestrator ?? answeringOrchestrator,
    resume: options.resume,
    history: options.history,
  } as unknown as HalServerOptions;
  const hal = createServer(serverOptions);
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {auth, base: `ws://127.0.0.1:${port}/hal/ws`};
};

const open = (url: string, token = 't'): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
};

const connectAndAsk = async (url: string, request: Record<string, unknown>): Promise<Frame> => {
  const client = open(url);
  return new Promise<Frame>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') {
        client.send(JSON.stringify(request));
        return;
      }
      resolve(frame);
    });
  });
};

const delegatingWithoutListFor = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

describe('listing conversations over the WebSocket protocol', () => {
  it("lists the connecting user's conversations newest first as ISO timestamps, pages with limit and before, and rejoins a listed id on reconnect", async () => {
    const store = new InMemorySessionStore();
    const older = store.create('older', 'u1');
    older.entries.push({role: 'user', content: 'first question', timestamp: '2026-09-30T08:00:00.000Z'});
    const newer = store.create('newer', 'u1');
    newer.entries.push(
      {role: 'user', content: 'second question', timestamp: '2026-09-30T09:00:00.000Z'},
      {role: 'assistant', content: 'second answer', timestamp: '2026-09-30T09:00:05.000Z', isStreaming: false}
    );
    const theirs = store.create('theirs', 'u2');
    theirs.entries.push({role: 'user', content: 'not yours', timestamp: '2026-09-30T10:00:00.000Z'});

    const engine = createHalEngine({
      provider: {type: 'mock'},
      prompt: {identity: 'test'},
      session: store,
      auth: {ws: async () => ({id: 'u1'})},
      transport: {
        port: 0,
        resume: {enabled: true},
        history: {enabled: true},
      } as unknown as NonNullable<Parameters<typeof createHalEngine>[0]['transport']>,
    });
    await engine.start(0);
    servers.push(engine);
    const {port} = engine.server.address() as AddressInfo;
    const base = `ws://127.0.0.1:${port}/hal/ws`;

    // Opening the socket creates a fresh session for this connection too; ask for all of u1's conversations.
    const fullList = await connectAndAsk(base, {type: 'list_conversations', userId: 'u2'});
    const firstPage = await connectAndAsk(base, {type: 'list_conversations', limit: 1, before: fullList.conversations?.[0]});

    // Reconnect naming the listed 'older' conversation to prove the end-to-end loop with #124.
    const reconnected = open(`${base}?sessionId=${older.sessionId}`);
    const [greeting] = (await once(reconnected, 'message')) as [Buffer];
    const connectedFrame = JSON.parse(String(greeting)) as Frame;

    const listedForOlder = fullList.conversations?.find(row => row.sessionId === 'older');
    const listedForNewer = fullList.conversations?.find(row => row.sessionId === 'newer');

    expect({
      type: fullList.type,
      includesTheirs: fullList.conversations?.some(row => row.sessionId === 'theirs'),
      newerBeforeOlder:
        (fullList.conversations?.findIndex(row => row.sessionId === 'newer') ?? -1) <
        (fullList.conversations?.findIndex(row => row.sessionId === 'older') ?? -1),
      newerSummary: listedForNewer && {
        sessionId: listedForNewer.sessionId,
        updatedAt: listedForNewer.updatedAt,
        entryCount: listedForNewer.entryCount,
        createdAtIso: typeof listedForNewer.createdAt === 'string' && !Number.isNaN(Date.parse(listedForNewer.createdAt)),
        keys: Object.keys(listedForNewer).sort(),
      },
      olderSummary: listedForOlder && {
        sessionId: listedForOlder.sessionId,
        updatedAt: listedForOlder.updatedAt,
        entryCount: listedForOlder.entryCount,
      },
      pagedIds: firstPage.conversations?.map(row => row.sessionId),
      rejoined: {sessionId: connectedFrame.sessionId, resumed: connectedFrame.resumed, entryCount: connectedFrame.entryCount},
    }).toEqual({
      type: 'conversation_list',
      includesTheirs: false,
      newerBeforeOlder: true,
      newerSummary: {
        sessionId: 'newer',
        updatedAt: '2026-09-30T09:00:05.000Z',
        entryCount: 2,
        createdAtIso: true,
        keys: ['createdAt', 'entryCount', 'sessionId', 'updatedAt'],
      },
      olderSummary: {
        sessionId: 'older',
        updatedAt: '2026-09-30T08:00:00.000Z',
        entryCount: 1,
      },
      pagedIds: ['newer'],
      rejoined: {sessionId: 'older', resumed: true, entryCount: 1},
    });
  });

  it('answers list_conversations at once while a user_message turn is still streaming', async () => {
    const gate = deferred();
    const streamingOrchestrator: ChatOrchestrator = {
      processMessage: async () => 'done',
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'streaming...'};
        await gate.until;
        yield {type: 'stop', stopReason: 'end_turn'};
      },
    };
    const store = new InMemorySessionStore();
    const {base} = await startServer(store, {history: {enabled: true}, orchestrator: streamingOrchestrator});

    const client = open(base);
    const seenTypes: string[] = [];
    await new Promise<void>(resolve => {
      client.on('message', raw => {
        const frame = JSON.parse(String(raw)) as Frame;
        seenTypes.push(frame.type);
        if (frame.type === 'connected') {
          client.send(JSON.stringify({type: 'user_message', content: 'start turn'}));
        }
        if (frame.type === 'entry_delta') {
          client.send(JSON.stringify({type: 'list_conversations'}));
        }
        if (frame.type === 'conversation_list' || frame.type === 'error') {
          gate.release();
        }
        if (frame.type === 'stream_end') resolve();
      });
    });

    expect({
      listIndex: seenTypes.indexOf('conversation_list'),
      beforeStreamEnd:
        seenTypes.includes('conversation_list') &&
        seenTypes.indexOf('conversation_list') < seenTypes.indexOf('stream_end'),
    }).toEqual({
      listIndex: expect.any(Number),
      beforeStreamEnd: true,
    });
  });

  it('answers UNSUPPORTED when history is off or the store lacks listFor, INVALID_MESSAGE on malformed paging, and SERVER_ERROR when listFor throws', async () => {
    const inner = new InMemorySessionStore();
    const historyOff = await startServer(inner);
    const noListFor = await startServer(delegatingWithoutListFor(inner), {history: {enabled: true}});
    const throwingStore: SessionStore = {
      ...delegatingWithoutListFor(inner),
      listFor: () => {
        throw new Error('database unreachable');
      },
    };
    const failing = await startServer(throwingStore, {history: {enabled: true}});
    const historyOn = await startServer(inner, {history: {enabled: true}});

    const offFrame = await connectAndAsk(historyOff.base, {type: 'list_conversations'});
    const absentFrame = await connectAndAsk(noListFor.base, {type: 'list_conversations'});
    const badLimit = await connectAndAsk(historyOn.base, {type: 'list_conversations', limit: 0});
    const highLimit = await connectAndAsk(historyOn.base, {type: 'list_conversations', limit: 201});
    const badBefore = await connectAndAsk(historyOn.base, {
      type: 'list_conversations',
      before: {updatedAt: 'not-a-date', sessionId: 's1'},
    });
    const halfBefore = await connectAndAsk(historyOn.base, {
      type: 'list_conversations',
      before: {updatedAt: '2026-09-30T08:00:00.000Z'},
    });
    const errorFrame = await connectAndAsk(failing.base, {type: 'list_conversations'});

    expect({
      off: {type: offFrame.type, code: offFrame.code},
      absent: {type: absentFrame.type, code: absentFrame.code},
      badLimit: {type: badLimit.type, code: badLimit.code},
      highLimit: {type: highLimit.type, code: highLimit.code},
      badBefore: {type: badBefore.type, code: badBefore.code},
      halfBefore: {type: halfBefore.type, code: halfBefore.code},
      failing: {type: errorFrame.type, code: errorFrame.code},
    }).toEqual({
      off: {type: 'error', code: 'UNSUPPORTED'},
      absent: {type: 'error', code: 'UNSUPPORTED'},
      badLimit: {type: 'error', code: 'INVALID_MESSAGE'},
      highLimit: {type: 'error', code: 'INVALID_MESSAGE'},
      badBefore: {type: 'error', code: 'INVALID_MESSAGE'},
      halfBefore: {type: 'error', code: 'INVALID_MESSAGE'},
      failing: {type: 'error', code: 'SERVER_ERROR'},
    });
  });
});
